export const es = Object.fromEntries(rows.map(([en, value]) => [en, value]));
export const vi = Object.fromEntries(rows.map(([en, , value]) => [en, value]));

// Story voices acquire typographic quotes at render time; source links acquire an arrow.
for (const [en, spanish, vietnamese] of rows) {
  if (!en.startsWith("“")) {
    es[`“${en}”`] = `“${spanish}”`;
    vi[`“${en}”`] = `“${vietnamese}”`;
  }
  if (en.startsWith("NASA") && !en.endsWith("↗")) {
    es[`${en} ↗`] = `${spanish} ↗`;
    vi[`${en} ↗`] = `${vietnamese} ↗`;
  }
}

// Inspecting a 3D part also reads its name and explanation as one announcement.
const partNames = new Set([
  "Mastcam eyes", "Robotic arm & turret", "Radioisotope power", "Wheels & suspension",
  "Counter-rotating rotors", "Solar panel", "Fuselage", "Landing legs",
  "Primary mirror", "Secondary mirror", "Mirror backplane", "Five-layer sunshield", "Science instruments",
  "Sounds of Earth record", "Playback diagram", "Image decoding", "Pulsar map",
]);
for (let index = 0; index < rows.length; index++) {
  const [en, spanish, vietnamese] = rows[index];
  if (!partNames.has(en)) continue;
  es[en.toUpperCase()] = spanish.toLocaleUpperCase("es");
  vi[en.toUpperCase()] = vietnamese.toLocaleUpperCase("vi");
  const [description, spanishDescription, vietnameseDescription] = rows[index + 1];
  es[`${en}. ${description}`] = `${spanish}. ${spanishDescription}`;
  vi[`${en}. ${description}`] = `${vietnamese}. ${vietnameseDescription}`;
}

